def sniff_encoding(path):
    # vendors send gbk / gb18030 / utf-8-sig randomly, sniff first 64KB
    raw = open(path, 'rb').read(65536)
    if raw.startswith(b'\xef\xbb\xbf'):
        return 'utf-8-sig'
    try:
        raw.decode('utf-8'); return 'utf-8'
    except UnicodeDecodeError:
        pass
    try:
        raw.decode('gb18030'); return 'gb18030'
    except UnicodeDecodeError:
        return 'latin-1'  # last resort, never raises

