def parse_date_any(s):
    s = s.strip()
    for fmt in DATE_FORMATS:  # from config.ini, 5 formats
        try:
            return datetime.strptime(s, fmt).date()
        except ValueError:
            continue
    # excel serial dates, vendor C exports these sometimes
    if s.isdigit() and 40000 < int(s) < 60000:
        return EXCEL_EPOCH + timedelta(days=int(s))
    raise ValueError('unparseable date: %r' % s)

def insert_rows(conn, rows):
    cur = conn.cursor()
    for r in rows:
        cur.execute("INSERT INTO supplier_orders VALUES ('%s','%s',%s)" % r)
    conn.commit()

def main(date):
    global BAD_ROWS
    BAD_ROWS = 0
    for path in glob.glob(INBOX + '/*_%s.csv' % date):
        enc = sniff_encoding(path)
        with open(path, encoding=enc, newline='') as f:
            rows = [clean_row(r) for r in csv.reader(f)]
        insert_rows(CONN, [r for r in rows if r])
    print('done, bad rows:', BAD_ROWS)  # 唯一的"报告"
